func TestImportDerivesTrainingLapsAndEfforts(t *testing.T) {
	ctx := context.Background()
	im := newImporter(t)
	o := fittest.Default()
	o.Training, o.Laps = true, 3
	res := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, o)), "upload:ride.fit")
	if res.Status != store.Created {
		t.Fatalf("%+v", res)
	}
	a, _ := im.Store.Get(ctx, res.ActivityID)
	if a.Training.Load != 50 || a.Training.Effect != 3.3 || a.AnalysisVersion != AnalysisVersion {
		t.Errorf("training %+v version %d", a.Training, a.AnalysisVersion)
	}
	laps, _ := im.Store.Laps(ctx, res.ActivityID)
	if len(laps) != 3 || laps[0].Auto || laps[2].StartS != 40 || laps[2].EndS != 60 {
		t.Errorf("laps %+v", laps)
	}
	// 60 s at 210 W: power curve up to one minute, no distance (480 m) or climb.
	eff, _ := im.Store.Efforts(ctx, res.ActivityID)
	if len(eff) != 4 || eff[0].Kind != store.EffortPower || eff[0].Key != 5 || eff[0].Value != 210 || eff[3].Key != 60 {
		t.Errorf("efforts %+v", eff)
	}
}

func TestLongRideGetsAutomaticSplits(t *testing.T) {
	ctx := context.Background()
	im := newImporter(t)
	o := fittest.Default()
	o.Points = 1500 // 12 km at 8 m/s, one lap
	res := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, o)), "upload:long.fit")
	laps, _ := im.Store.Laps(ctx, res.ActivityID)
	if len(laps) != 3 || !laps[0].Auto || laps[0].DistanceM != 5000 || laps[2].DistanceM < 1900 {
		t.Fatalf("splits %+v", laps)
	}
	eff, _ := im.Store.Efforts(ctx, res.ActivityID)
	var five, ten float64
	for _, e := range eff {
		if e.Kind == store.EffortDistance && e.Key == 5000 {
			five = e.Value
		}
		if e.Kind == store.EffortDistance && e.Key == 10000 {
			ten = e.Value
		}
	}
	if five != 625 || ten != 1250 {
		t.Errorf("5 km %v s, 10 km %v s", five, ten)
	}
}

func TestReanalyzeUsesArchivedRawFile(t *testing.T) {
	ctx := context.Background()
	im := newImporter(t)
	o := fittest.Default()
	o.Laps = 2
	raw := fittest.Encode(t, o)
	act, err := fitfile.Decode(raw)
	if err != nil {
		t.Fatal(err)
	}
	// State of an older release: archived file, activity derived with version 1.
	if err := im.archive(act.SHA256, raw); err != nil {
		t.Fatal(err)
	}
	old, err := recording(act, "export:old.fit", nil)
	if err != nil {
		t.Fatal(err)
	}
	old.Activity.AnalysisVersion, old.Laps, old.Efforts = 1, nil, nil
	id, _, err := im.Store.SaveRecording(ctx, old)
	if err != nil {
		t.Fatal(err)
	}
	// A second outdated activity whose raw file is gone.
	gone := old
	gone.Key, gone.SHA256 = "fit:1:9:9", "ffff"
	if _, _, err := im.Store.SaveRecording(ctx, gone); err != nil {
		t.Fatal(err)
	}

	if n, _ := im.Outdated(ctx); n != 2 {
		t.Fatalf("outdated %d", n)
	}
	var results []Result
	stats, err := im.Reanalyze(ctx, func(r Result) { results = append(results, r) })
	if err != nil || stats.Updated != 1 || stats.Failed != 1 {
		t.Fatalf("stats %+v err %v results %+v", stats, err, results)
	}
	if laps, _ := im.Store.Laps(ctx, id); len(laps) != 2 {
		t.Errorf("laps after reanalysis: %d", len(laps))
	}
	if n, _ := im.Outdated(ctx); n != 1 {
		t.Errorf("only the missing file stays outdated: %d", n)
	}
	// Running again does not touch up-to-date activities.
	if stats, _ := im.Reanalyze(ctx, nil); stats.Updated != 0 || stats.Failed != 1 {
		t.Errorf("second run %+v", stats)
	}
	if _, err := os.Stat(filepath.Join(im.RawDir, act.SHA256[:2], act.SHA256+".fit")); err != nil {
		t.Errorf("raw file must stay: %v", err)
	}
}

